INSERT INTO `skinning_loot_template` (`Entry`, `Item`, `Reference`, `Chance`, `QuestRequired`, `LootMode`, `GroupId`, `MinCount`, `MaxCount`, `Comment`) VALUES
(100026, 783, 0, 5.362, 0, 1, 1, 1, 1, NULL),
(100026, 2318, 0, 73.71, 0, 1, 1, 1, 1, NULL),
