INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(50580, 50, 0, 'There\'s certain percentage of probability our team will reach the successful ending of the race this time. Unlike some poorly educated goblins, of course.', 12, 0, 0, 0, 0, 0, 0, 0, 'Gnome Pit Crewman - Gnome Crew Member Speaking'),
(50581, 50, 0, 'Success probability high. Rival team tiumph is close to nonexistant. Result acceptable. Proceed with glory!', 12, 0, 0, 0, 0, 0, 0, 0, 'Gnome Pit Crewman - Gnome Crew Member Speaking'),
(50582, 50, 0, 'Who? THEM? Hahahah! What a nice joke! Sounds like as if goblins would be aware of term invention whatsoever.', 12, 0, 0, 0, 0, 0, 0, 0, 'Gnome Pit Crewman - Gnome Crew Member Speaking'),
(50583, 50, 0, 'It takes quit a bit of brain capacity to calculate the probabilities and analyze possible outcome for successful start of any machine. Something any gnome would easily do, naturally. Pff, of course, we\'re not some kind of green nosey frauds you know.', 12, 0, 0, 0, 0, 0, 0, 0, 'Gnome Pit Crewman - Gnome Crew Member Speaking'),
(50584, 50, 0, 'There\'s two words you should take into account here; Rocket and Science. Make a wild guess who has both? Exactly – gnomes!', 12, 0, 0, 0, 0, 0, 0, 0, 'Gnome Pit Crewman - Gnome Crew Member Speaking'),
(50585, 50, 0, 'Alright then, kid, just take a step or two back. I\'m sure this is gonna blast out nicely. I think…', 12, 0, 0, 0, 0, 0, 0, 0, 'Goblin Pit Crewman - Goblin Crew Member Speaking'),
(50586, 50, 0, 'Bah! While these baldlings do their calculations and draw their plans we\'ll have this place flying up high with just a grain of salt and some rocks blasting the blasted place ... eerrr, you got it, kid! BOOM!', 12, 0, 0, 0, 0, 0, 0, 0, 'Goblin Pit Crewman - Goblin Crew Member Speaking'),
(50587, 50, 0, 'FIRE IN THE HOLE!', 12, 0, 0, 0, 0, 0, 0, 0, 'Goblin Pit Crewman - Goblin Crew Member Speaking'),
(50588, 50, 0, 'It\'s about explosions, kid! Biggest BOOM brings the best price!', 12, 0, 0, 0, 0, 0, 0, 0, 'Goblin Pit Crewman - Goblin Crew Member Speaking'),
(50589, 50, 0, 'Boy, Gazlowe would go green with jealousy, envy and spite over such a blast! Oh, wait…', 12, 0, 0, 0, 0, 0, 0, 0, 'Goblin Pit Crewman - Goblin Crew Member Speaking'),
(50590, 50, 0, 'Time is money and we always lack money since there\'s so many things we gotta blow up and there\'s always only this much money you have. At least we got paid for blowing things up, unlike some "inventors". Haha!', 12, 0, 0, 0, 0, 0, 0, 0, 'Goblin Pit Crewman - Goblin Crew Member Speaking'),
(50591, 50, 0, 'Gnomes this ... Gnomes that ... We learn how to blast things before we even start walking, ha!', 12, 0, 0, 0, 0, 0, 0, 0, 'Goblin Pit Crewman - Goblin Crew Member Speaking'),
(50592, 50, 0, 'If blasting powder didn\'t fix it then you use not enough blasting powder!', 12, 0, 0, 0, 0, 0, 0, 0, 'Goblin Pit Crewman - Goblin Crew Member Speaking');
