INSERT INTO `quest_offer_reward` (`ID`, `Emote1`, `Emote2`, `Emote3`, `Emote4`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `EmoteDelay4`, `RewardText`, `VerifiedBuild`) VALUES
(41053, 0, 0, 0, 0, 0, 0, 0, 0, 'You have retrieved the message. Good work. Now show me that.$B$B<Commander Anashya takes the message from you and carefully reads it, her eyes scanning the words with a furrowed brow>$B$BInteresting... They are preparing to attack the tauren.', 0),
(41054, 0, 0, 0, 0, 0, 0, 0, 0, 'Your efforts have yielded crucial time for the tauren, and our diplomat has returned from their meeting. The tauren expressed deep gratitude for the information provided, and their appreciation resonates within our hearts.$B$BNever again shall shame befall us.', 0),
(41967, 0, 0, 0, 0, 0, 0, 0, 0, '<Brolan Windhorn lets out a deep sigh of relief.>$B$BYou have saved me much turmoil, now that I know I can sleep more at peace. You have done the Windhorn a great service this day, and I offer you a token of our appreciation outsider.', 0),
(41977, 0, 0, 0, 0, 0, 0, 0, 0, 'I spent the entirety of my youth surrounded by such relics. The craftsmanship of the Windhorn is certainly superb.$B$BWithout your help, this history would have been lost to time. I thank you, for everything that you have done this day.', 0),
(41978, 0, 0, 0, 0, 0, 0, 0, 0, 'Blood for blood. You have done well, and repaid this evil with vengeance. I hope you feel the satisfaction that I feel, for I am vindicated, even if anger still burns deep in my heart.$B$BI must thank you for being the hand of my wrath. Please, take these coins, as tribute from me, and those lost.', 0),
(41979, 0, 0, 0, 0, 0, 0, 0, 0, '<Cairne takes the letter, gazing it over with a stern, an serious gaze.>$B$BLonghorn was right to send you, this matter could bring dire consequence.', 0),
(41980, 0, 0, 0, 0, 0, 0, 0, 0, 'A letter, from Cairne?', 0),
(41981, 0, 0, 0, 0, 0, 0, 0, 0, '<Cairne takes a moment to process the information, his hand rubbing against his jaw.>$B$BWindhorn Canyon. I did hear about trouble there from the Windhorn Tribe who were expelled.', 0);
INSERT INTO `quest_request_items` (`ID`, `EmoteOnComplete`, `EmoteOnIncomplete`, `CompletionText`, `VerifiedBuild`) VALUES
(41053, 0, 0, 'Do not disappoint me.', 0),
(41054, 0, 0, 'Centaurs can be found mostly in the northern parts of Thousand Needles. Waste no time.', 0),
(41967, 0, 0, 'Our numbers have already been thinned, I must ensure that not one more of our already beleaguered kin is brought to an untimely death.', 0),
(41977, 0, 0, 'Tread carefully, the Grimtotem have fortified Windhorn Canyon and claimed it as their own. The large, steep cliffs provide an excellent redoubt for defence. I advise you to bring allies if you wish to help.', 0),
(41978, 0, 0, 'It is only a matter of time before they feel what I have felt. They shall pay for their actions, and I shall have my revenge.', 0),
(41979, 0, 0, 'What brings you to Thunderbluff?', 0),
(41980, 0, 0, 'What business do you have?', 0),
(41981, 0, 0, 'Yes?', 0);
